alter table public.paper_portfolios alter column user_id drop not null;
alter table public.paper_portfolios add column if not exists policy_version text,add column if not exists base_currency text not null default 'SEK',add column if not exists portfolio_scope text not null default 'USER' check(portfolio_scope in('USER','SYSTEM_RESEARCH'));
alter table public.paper_portfolios add constraint paper_portfolios_policy_version_key unique(policy_version);
alter table public.paper_positions add column if not exists cost_basis numeric(24,2) not null default 0,add column if not exists current_price numeric(24,10),add column if not exists market_value numeric(24,2) not null default 0,add column if not exists realized_pnl numeric(24,2) not null default 0,add column if not exists unrealized_pnl numeric(24,2) not null default 0,add column if not exists high_watermark numeric(24,10);
create table public.paper_policies(id uuid primary key default gen_random_uuid(),policy_version text not null unique,name text not null,kind text not null,config jsonb not null,config_hash text not null unique,status text not null check(status in('DRAFT','ACTIVE','RETIRED')),activated_at timestamptz,created_at timestamptz not null default now());
alter table public.paper_portfolios add constraint paper_portfolios_policy_version_fkey foreign key(policy_version) references public.paper_policies(policy_version);
create table public.paper_policy_evaluations(id uuid primary key default gen_random_uuid(),portfolio_id uuid not null references public.paper_portfolios(id),policy_id uuid not null references public.paper_policies(id),candidate_id uuid not null references public.jackpot_candidates(id),candidate_revision integer not null,decision_cutoff timestamptz not null,status text not null check(status in('ELIGIBLE','REJECTED','WATCH')),reason text not null,requested_amount numeric(24,2) not null default 0,known_inputs jsonb not null,evaluation_hash text not null unique,created_at timestamptz not null default now());
create table public.paper_orders(id uuid primary key default gen_random_uuid(),portfolio_id uuid not null references public.paper_portfolios(id),policy_id uuid not null references public.paper_policies(id),evaluation_id uuid not null references public.paper_policy_evaluations(id),candidate_id uuid not null references public.jackpot_candidates(id),opportunity_id uuid references public.opportunities(id),asset_id uuid not null references public.assets(id),side text not null check(side in('BUY','SELL')),signal_available_at timestamptz not null,decision_at timestamptz not null,configured_entry_delay_ms integer not null,simulated_execution_at timestamptz not null,requested_amount numeric(24,2) not null,executed_amount numeric(24,2) not null default 0,signal_price numeric(24,10),execution_price numeric(24,10),fees jsonb not null default'{}',slippage jsonb not null default'{}',liquidity_used numeric(24,2),status text not null check(status in('CREATED','ELIGIBLE','REJECTED','SIMULATED','FILLED','PARTIALLY_FILLED','CANCELLED','EXPIRED')),reason text,idempotency_key text not null unique,created_at timestamptz not null default now());
create table public.paper_fills(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.paper_orders(id),portfolio_id uuid not null references public.paper_portfolios(id),position_id uuid references public.paper_positions(id),side text not null,quantity numeric(38,18) not null,price numeric(24,10) not null,principal numeric(24,2) not null,fees numeric(24,2) not null,cash_before numeric(24,2) not null,cash_after numeric(24,2) not null,executed_at timestamptz not null,fill_hash text not null unique,created_at timestamptz not null default now());
create table public.paper_equity_points(id uuid primary key default gen_random_uuid(),portfolio_id uuid not null references public.paper_portfolios(id),captured_at timestamptz not null,cash numeric(24,2) not null,open_position_value numeric(24,2) not null,realized_pnl numeric(24,2) not null,unrealized_pnl numeric(24,2) not null,total_equity numeric(24,2) not null,information_cutoff_at timestamptz not null,pricing_source text not null,data_quality smallint not null,point_hash text not null unique,created_at timestamptz not null default now());
create table public.paper_trade_attribution(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.paper_orders(id),candidate_id uuid references public.jackpot_candidates(id),opportunity_id uuid references public.opportunities(id),candidate_revision integer,fast_flow_revision integer,policy_version text not null,agent_output_refs jsonb not null default'[]',attribution_hash text not null unique,created_at timestamptz not null default now());
create or replace function public.prevent_paper_history_mutation()returns trigger language plpgsql as $$begin raise exception'Paper research history is immutable';end$$;
create trigger paper_policies_immutable before update or delete on public.paper_policies for each row when(old.status='ACTIVE')execute function public.prevent_paper_history_mutation();create trigger paper_evaluations_immutable before update or delete on public.paper_policy_evaluations for each row execute function public.prevent_paper_history_mutation();create trigger paper_fills_immutable before update or delete on public.paper_fills for each row execute function public.prevent_paper_history_mutation();create trigger paper_equity_immutable before update or delete on public.paper_equity_points for each row execute function public.prevent_paper_history_mutation();create trigger paper_attribution_immutable before update or delete on public.paper_trade_attribution for each row execute function public.prevent_paper_history_mutation();
alter table public.paper_policies enable row level security;alter table public.paper_policy_evaluations enable row level security;alter table public.paper_orders enable row level security;alter table public.paper_fills enable row level security;alter table public.paper_equity_points enable row level security;alter table public.paper_trade_attribution enable row level security;
create policy "public read system paper portfolios" on public.paper_portfolios for select using(portfolio_scope='SYSTEM_RESEARCH');create policy "public read active paper policies" on public.paper_policies for select using(status='ACTIVE');create policy "public read system paper evaluations" on public.paper_policy_evaluations for select using(exists(select 1 from public.paper_portfolios p where p.id=portfolio_id and p.portfolio_scope='SYSTEM_RESEARCH'));create policy "public read system paper orders" on public.paper_orders for select using(exists(select 1 from public.paper_portfolios p where p.id=portfolio_id and p.portfolio_scope='SYSTEM_RESEARCH'));create policy "public read system paper fills" on public.paper_fills for select using(exists(select 1 from public.paper_portfolios p where p.id=portfolio_id and p.portfolio_scope='SYSTEM_RESEARCH'));create policy "public read system paper equity" on public.paper_equity_points for select using(exists(select 1 from public.paper_portfolios p where p.id=portfolio_id and p.portfolio_scope='SYSTEM_RESEARCH'));create policy "public read system paper attribution" on public.paper_trade_attribution for select using(exists(select 1 from public.paper_orders o join public.paper_portfolios p on p.id=o.portfolio_id where o.id=order_id and p.portfolio_scope='SYSTEM_RESEARCH'));
grant select on public.paper_policies,public.paper_policy_evaluations,public.paper_orders,public.paper_fills,public.paper_equity_points,public.paper_trade_attribution to anon,authenticated;grant all on public.paper_policies,public.paper_policy_evaluations,public.paper_orders,public.paper_fills,public.paper_equity_points,public.paper_trade_attribution to service_role;
alter table public.ingestion_runs drop constraint if exists ingestion_runs_job_kind_check;alter table public.ingestion_runs add constraint ingestion_runs_job_kind_check check(job_kind in('stock_quotes','wallet_transactions','wallet_discovery','crypto_market','wallet_pnl','wallet_evidence','fast_flow','wallet_clustering','jackpot_collector','jackpot_outcomes','market_events','paper_eligibility','paper_execution','paper_exits','paper_valuation'));
